# frozen_string_literal: true

# Generates sig/array_sort.rbs from the algorithm registry, so the type signatures always list every sort method.
#
#   bundle exec rake sig
#
# test/array_sort/sig_test.rb fails if the committed file is out of date.

require_relative '../lib/array_sort'

# Renders the RBS signatures for ArraySort's public API.
module SigGenerator
  PATH = File.expand_path('../sig/array_sort.rbs', __dir__)

  module_function

  def render
    <<~RBS
      # Generated by script/generate_sig.rb from the algorithm registry; run `bundle exec rake sig` to update.

      module ArraySort
        VERSION: String

        type real = Integer | Float | Rational

        def self.algorithms: () -> Array[Symbol]
        def self.algorithm: (Symbol | String name) -> Algorithm
        def self.trace: (Symbol | String name, Array[untyped] array) ?{ (Trace::event event) -> void } -> Trace

      #{module_functions.join("\n").gsub(/^(?=.)/, '  ')}
        class Algorithm < Data
          attr_reader name: Symbol
          attr_reader title: String
          attr_reader implementation: untyped
          attr_reader stable: bool
          attr_reader kind: :comparison | :distribution
          attr_reader best: String
          attr_reader average: String
          attr_reader worst: String
          attr_reader space: String
          def stable?: () -> bool
          def comparison?: () -> bool
          def distribution?: () -> bool
        end

        class Trace
          type event = Comparison | Write

          class Comparison < Data
            attr_reader left: untyped
            attr_reader right: untyped
            attr_reader result: Integer
          end

          class Write < Data
            attr_reader index: Integer
            attr_reader value: untyped
          end

          attr_reader algorithm: Algorithm
          attr_reader input: Array[untyped]
          attr_reader result: Array[untyped]
          attr_reader events: Array[event]
          def comparisons: () -> Integer
          def writes: () -> Integer
        end

        module ArrayMethods[Elem]
          def swap: (Integer index1, Integer index2) -> self

      #{array_methods.join("\n").gsub(/^(?=.)/, '    ')}
        end

        module Refinements
        end
      end

      class Array[unchecked out Elem]
        include ArraySort::ArrayMethods[Elem]
      end
    RBS
  end

  def array_methods
    ArraySort.algorithms.map do |name|
      algorithm = ArraySort.algorithm(name)
      compare_block = algorithm.comparison? ? '?{ (Elem a, Elem b) -> Numeric? } ' : ''
      key = key_type(algorithm, 'untyped')
      <<~RBS
        def #{name}_sort: () #{compare_block}-> Array[Elem]
        def #{name}_sort!: () #{compare_block}-> self
        #{overloads("def #{name}_sort_by", "() { (Elem) -> #{key} } -> Array[Elem]", '() -> Enumerator[Elem, Array[Elem]]')}
        #{overloads("def #{name}_sort_by!", "() { (Elem) -> #{key} } -> self", '() -> Enumerator[Elem, self]')}
      RBS
    end
  end

  def module_functions
    ArraySort.algorithms.map do |name|
      algorithm = ArraySort.algorithm(name)
      compare_block = algorithm.comparison? ? '?{ (T a, T b) -> Numeric? } ' : ''
      element = algorithm.comparison? ? 'T' : key_type(algorithm, 'T')
      key = key_type(algorithm, 'untyped')
      enumerator = '[T] (Array[T] array) -> Enumerator[T, Array[T]]'
      <<~RBS
        def self.#{name}_sort: [T] (Array[#{element}] array) #{compare_block}-> Array[#{element}]
        def self.#{name}_sort!: [T] (Array[#{element}] array) #{compare_block}-> Array[#{element}]
        #{overloads("def self.#{name}_sort_by", "[T] (Array[T] array) { (T) -> #{key} } -> Array[T]", enumerator)}
        #{overloads("def self.#{name}_sort_by!", "[T] (Array[T] array) { (T) -> #{key} } -> Array[T]", enumerator)}
      RBS
    end
  end

  # A method with two overloads, the second lined up under the first.
  def overloads(definition, first, second)
    "#{definition}: #{first}\n#{' ' * definition.length}| #{second}"
  end

  # The key (or element) type an algorithm accepts: anything for comparison sorts, Integers for counting and radix
  # sort, and real numbers for bucket sort.
  def key_type(algorithm, otherwise)
    return otherwise if algorithm.comparison?

    algorithm.name == :bucket ? 'real' : 'Integer'
  end
end

File.write(SigGenerator::PATH, SigGenerator.render) if $PROGRAM_NAME == __FILE__
